import os
import sys
from typing import Any, Sequence

def _get_platform_max_length():
    if hasattr(os, 'get_terminal_size'):
        width, _ = os.get_terminal_size()
        return width
    return 80

def _spawn_process(cmd, args):
    return os.spawnvp(os.P_WAIT, cmd, args)

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    if color:
        args = list(cmd) + varargs
        if os.isatty(1):
            cmd = 'script' + ('-q' if not color else '') + ' -c "' + ' '.join(cmd) + ' ' + ' '.join(varargs) + '"'
    else:
        args = cmd + varargs

    length = sum(len(arg) for arg in args)
    if length <= _max_length:
        return _spawn_process(args[0].encode(), args[1:], **kwargs)

    partitions = [args[i:i+target_concurrency] for i in range(0, len(args), target_concurrency)]
    processes = [os.fork() for _ in range(len(partitions))]
    for pid, partition in zip(processes, partitions):
        if pid == 0:
            _spawn_process(partition[0].encode(), partition[1:], **kwargs)
        else:
            os.waitpid(pid, 0)

    return 0, b''

