def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os
    import re

    def normalize_path(path: str) -> str:
        return os.path.abspath(path)

    def fix_shebang(shebang: str) -> str:
        # Remove \r from shebang, as it's picked up by Windows cmd
        return shebang.replace('\r', '')

    def simplify_path(shebang: str) -> str:
        match = re.match(r'^#!(.*)', shebang)
        if match:
            path = match.group(1).strip()
            if not os.path.isabs(path):
                shebang = shebang.replace(path, normalize_path(path))
        return shebang

    if cmd and cmd[0].startswith('#!'):
        cmd[0] = simplify_path(fix_shebang(cmd[0]))

    return cmd

