                    if entry['expire'] > self.timer():
                        return entry['value']
                    del self.cache[key]
                result = func(*args, **kwargs)
                self.cache[key] = {'expire': self.timer() + self.ttl, 'value': result}
                if len(self.cache) > maxsize:
                    oldest_key = min(self.cache, key=lambda k: self.cache[k]['expire'])
                    del self.cache[oldest_key]
                return result
            return wrapper

    return TTLCache(maxsize, ttl, timer, typed)

