def lru_cache(maxsize=128, typed=False):
    class LRUCache:
        def __init__(self, maxsize, typed):
            self.cache = {}
            self.maxsize = maxsize
            self.typed = typed
            self.access_order = []

        def _make_key(self, args, kwds):
            # Custom key creation based on args, kwds, and typed
            if typed:
                key = args, frozenset(kwds.items())
            else:
                key = args, tuple(sorted(kwds.items()))
            return key

        def __call__(self, func):
            def wrapper(*args, **kwds):
                key = self._make_key(args, kwds)
                if key in self.cache:
                    self.access_order.remove(key)
                    self.access_order.append(key)
                    return self.cache[key]
                result = func(*args, **kwds)
                if len(self.cache) >= self.maxsize:
                    oldest_key = self.access_order.pop(0)
                    del self.cache[oldest_key]
                self.cache[key] = result
                self.access_order.append(key)
                return result
            return wrapper

    return LRUCache(maxsize, typed)

