def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        class Node:
            def __init__(self, key, value, frequency=1):
                self.key = key
                self.value = value
                self.frequency = frequency

        cache = {}
        frequency_map = defaultdict(OrderedDict)
        min_frequency = 0

        def get(key):
            if key not in cache:
                return None
            node = cache[key]
            del frequency_map[node.frequency][key]
            node.frequency += 1
            frequency_map[node.frequency][key] = node
            if not frequency_map[min_frequency]:
                min_frequency += 1
            return node.value

        def set(key, value):
            nonlocal min_frequency
            if key in cache:
                node = cache[key]
                del frequency_map[node.frequency][key]
                node.value = value
                node.frequency += 1
                frequency_map[node.frequency][key] = node
                if not frequency_map[min_frequency]:
                    min_frequency += 1
            else:
                if len(cache) >= maxsize:
                    oldest_key, oldest_node = frequency_map[min_frequency].popitem(last=False)
                    del cache[oldest_key]
                node = Node(key, value)
                cache[key] = node
                frequency_map[node.frequency][key] = node
                min_frequency = 1

        def invalidate(key):
            if key in cache:
                del cache[key]
                for freq_map in frequency_map.values():
                    if key in freq_map:
                        del freq_map[key]
                        break

        def clear():
            nonlocal cache, frequency_map, min_frequency
            cache = {}
            frequency_map.clear()
            min_frequency = 0

        def __call__(self, *args, **kwargs):
            if typed:
                args_tuple = tuple(args)
                kwargs_tuple = tuple(kwargs.items())
                key = (func.__name__, args_tuple, kwargs_tuple)
            else:
                key = args + tuple(kwargs.items())
            set(key, func(*args, **kwargs))
            return get(key)

        return __call__

    return decorator

