def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    def find_parents(base):
        return classes[base] if base in classes else []

    def dfs(node, visited, stack):
        visited.add(node)
        for parent in find_parents(node):
            if parent not in visited:
                dfs(parent, visited, stack)
        stack.append(node)

    visited = set()
    stack = []
    for node in classes:
        if node not in visited:
            dfs(node, visited, stack)

    minimal = [stack.pop()]
    while stack:
        current = stack.pop()
        if all(current not in find_parents(base) for base in minimal):
            minimal.append(current)
    return minimal[::-1]

