def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    if self._is_within_edges(coord):
        index = self._coord_to_index(coord)
        self.bins[index] += weight

    def _is_within_edges(self, coord):
        """Check if the coordinate is within the histogram edges."""
        for edge, value in zip(self.edges, coord):
            if value < edge or value >= edge + self.edges[1] - self.edges[0]:
                return False
        return True

    def _coord_to_index(self, coord):
        """Convert coordinate to bin index."""
        return tuple(int((value - edge) / (self.edges[i+1] - self.edges[i])) for i, (edge, value) in enumerate(zip(self.edges, coord)))

