from kubernetes import client, config

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    core_v1 = client.CoreV1Api()
    apps_v1 = client.AppsV1Api()
    custom_objects_api = client.CustomObjectsApi()

    default_observer_schema = {}

    for resource in app.spec.manifest:
        resource_name = resource['kind'] + '_' + resource['metadata']['name']
        if 'schema' not in resource:
            try:
                if resource_name.startswith('ConfigMap_'):
                    resource_object = core_v1.read_namespaced_config_map(
                        name=resource['metadata']['name'],
                        namespace=app.spec.namespace
                    )
                    default_observer_schema[resource_name] = resource_object.to_dict()
                elif resource_name.startswith('Deployment_'):
                    resource_object = apps_v1.read_namespaced_deployment(
                        name=resource['metadata']['name'],
                        namespace=app.spec.namespace
                    )
                    default_observer_schema[resource_name] = resource_object.to_dict()
                elif resource_name.startswith('CustomResource_'):
                    group, version, plural = resource_name.split('_')[1:].split('_', 2)
                    resource_object = custom_objects_api.get_namespaced_custom_object(
                        group=group,
                        version=version,
                        namespace=app.spec.namespace,
                        plural=plural,
                        name=resource['metadata']['name']
                    )
                    default_observer_schema[resource_name] = resource_object
                else:
                    default_observer_schema[resource_name] = {}
            except client.rest.ApiException as e:
                print(f"Error retrieving {resource_name}: {e}")
        else:
            default_observer_schema[resource_name] = resource['schema']

    return default_observer_schema

