        out_params = [f"out_{v}" for v in params]
    return sql, out_params

def format sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]] -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]:
    if isinstance(params, Mapping):
        out_params = {f":param_{i}": v for i, (k, v) in enumerate(params.items(), 1)}
        sql = sql.replace("%s", "%(param_i)s")
    elif isinstance(params, Sequence):
        out_params = [v for v in params]
        sql = sql.replace("%s", "?")
    else:
        raise ValueError("Invalid params type. Must be a mapping or sequence.")
    return sql, out_params

def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(params, Mapping):
        out_params = {f"${k}": v for k, v in params.items()}
    elif isinstance(params, Sequence):
        out_params = [f":{i+1}" for i in range(len(params))]
    else:
        raise ValueError("params must be a Mapping or Sequence")

    sql = sql.replace("?", out_params.get("?", ""))
    formatted_sql = sql.replace("%s", out_params.get("%s", ""))
    formatted_sql = formatted_sql.replace("%d", out_params.get("%d", ""))
    formatted_sql = formatted_sql.replace("%f", out_params.get("%f", ""))

    return formatted_sql, out_params

def format(
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    # Split the SQL query into parts based on the in-style parameters
    sql_parts = sql.split()
    out_params: Union[Dict[Union[str, int], Any], Sequence[Any]]

    if isinstance(params, Mapping):
        out_params = {}
        param_index = 1
        for i, part in enumerate(sql_parts):
            if part.startswith(':'):
                param_name = part[1:]
                out_params[param_name] = params[param_index - 1]
                sql_parts[i] = f':{param_index}'
                param_index += 1
    elif isinstance(params, Sequence):
        out_params = []
        param_index = 1
        for i, part in enumerate(sql_parts):
            if part.startswith('%s' or ':param'):
                out_params.append(params[param_index - 1])
                sql_parts[i] = f':{param_index}'
                param_index += 1
    else:
        raise ValueError("Invalid params type. Expected a Mapping or Sequence.")

    formatted_sql = ' '.join(sql_parts)
    return formatted_sql, out_params

def formatmany(self, sql: AnyStr, many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]]) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    from collections.abc import Iterable, Mapping, Sequence
    import re

    def format_one_query(query: AnyStr, params: Union[Mapping[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Dict[Union[str, int], Any]]:
        in_style = self.SQLParams.in_style
        out_params: Dict[Union[str, int], Any] = {}
        formatted_query: AnyStr = query

        if in_style == ':':
            if not isinstance(params, Mapping):
                raise ValueError("Parameters must be a mapping for named style parameters")
            pattern = re.compile(r':(\w+)')
            match = pattern.findall(query)
            out_params = {key: params[key] for key in match}
            formatted_query = pattern.sub(r'%(\1)s', query)
        elif in_style == '?':
            if not isinstance(params, Sequence):
                raise ValueError("Parameters must be a sequence for ordinal style parameters")
            out_params = {str(i): param for i, param in enumerate(params, start=1)}
            formatted_query = query.replace('?', '%s', params.count('?'))
        else:
            raise ValueError("Unsupported parameter style")

        return formatted_query, out_params

    formatted_queries = []
    for params in many_params:
        formatted_query, out_param = format_one_query(sql, params)
        formatted_queries.append(out_param)

    return sql, formatted_queries

def formatmany(
    self,
    sql: AnyStr,
    many_params: Union[Iterable[Dict[Union[str, int], Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[Union[str, int], Any]], List[Sequence[Any]]]]:
    out_params_type = list if isinstance(next(iter(many_params)), dict) else list
    formatted_sql = sql
    converted_params = []

    for params in many_params:
        if isinstance(params, dict):
            formatted_sql = formatted_sql.replace('?', '{').format(**params)
        else:
            formatted_sql = formatted_sql.replace('?', '{').format(*params)
        converted_params.append(params)

    return formatted_sql, converted_params

