    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 3 and expr[1] in ('&', '|'):
            A, B = expr[0], expr[2]
            op = expr[1]
            if op == '&':
                result.append((A, '&', A if A == A | B else expr))
                result.append((A, '|', A if A == A & B else expr))
            elif op == '|':
                result.append((A, '&', A if A == ~A | B else expr))
                result.append((A, '|', A if A == ~A & B else expr))
        else:
