    return result

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if expr == "A & (A | B)":
            new_args.append("A")
        elif expr == "A | (A & B)":
            new_args.append("A")
        elif expr == "A & (~A | B)":
            new_args.append("A & B")
        elif expr == "A | (~A & B)":
            new_args.append("A | B")
        else:
            new_args.append(expr)
    return new_args

