def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    if sys.version_info[0] < 3:
        return [s.encode('utf-8') if isinstance(s, unicode) else s for s in namefunc()]
    else:
        return namefunc()

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] == 2:
        def wrapper():
            utc = namefunc()
            return [ut.decode('utf-8') for ut in utc]
        return wrapper
    else:
        return namefunc

