def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import sys

    if isinstance(commands, str):
        commands = [commands]

    for command in commands:
        if verbose:
            print(f"Running command: {command} {' '.join(args)}")
        process = subprocess.Popen([command] + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        stdout, stderr = process.communicate()

        if hide_stderr:
            stderr = ''

        if verbose:
            print(f"Command output: {stdout.decode()}")
            if stderr:
                print(f"Command error: {stderr.decode()}")

        if process.returncode != 0:
            print(f"Command failed with return code {process.returncode}")
            return process.returncode, stderr.decode()

    return 0, None

