def find_path_type(path):
    import os

    if not os.path.exists(path):
        return "path does not exist"

    if os.path.isfile(path):
        return "file"

    namaste_file = os.path.join(path, "0=*", "root.txt")
    if os.path.isfile(namaste_file):
        namaste_content = open(namaste_file, 'r').read().strip()
        if namaste_content == "OCFL_STORAGE_ROOT":
            return "root"
        elif namaste_content == "OCFL_OBJECT":
            return "object"

