    """
    import os

    if os.path.isdir(path):
        namaste_path = os.path.join(path, '0=*')
        if os.path.isfile(namaste_path):
            with open(namaste_path, 'r') as f:
                first_line = f.readline().strip()
                if first_line == 'OCFL Version: 0.5':
                    return 'root'
                elif first_line == 'ocfl_version: 1.0':
                    return 'object'
    elif os.path.isfile(path):
        return 'file'
    else:
        return 'not_found'

