    """
    try:
        namaste_file_path = f"{path}/.ocfl/namaste"
        with open(namaste_file_path, 'r') as file:
            first_line = file.readline().strip()
            if first_line == '0=*':
                if 'versionInventory=1.0' in file.read():
                    return 'root'
                else:
