import logging

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''

    config_dict = {}
    log_records = []

    try:
        for config_file in config_filenames:
            try:
                with open(config_file, 'r') as file:
                    config = dict(file.read().splitlines())
                    config_dict[config_file] = config
            except FileNotFoundError:
                log_records.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, 
                                                  pathname=config_file, lineno=1, msg=f"File not found: {config_file}", args=(), exc_info=None))
            except Exception as e:
                log_records.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, 
                                                  pathname=config_file, lineno=1, msg=f"Error parsing file {config_file}: {str(e)}", args=(), exc_info=None))

        if overrides:
            for config_file, overrides_dict in overrides.items():
                if config_file in config_dict:
                    config_dict[config_file].update(overrides_dict)
                else:
                    log_records.append(logging.LogRecord(name='load_configurations', level=logging.WARNING, 
                                                      pathname=config_file, lineno=1, msg=f"Overrides provided for non-existent config file: {config_file}", args=(), exc_info=None))

        if resolve_env:
            for config_file, config in config_dict.items():
                for key, value in config.items():
                    config[key] = value.replace("${", "").replace("}", "")

    except Exception as e:
        log_records.append(logging.LogRecord(name='load_configurations', level=logging.ERROR, 
                                          pathname='load_configurations', lineno=1, msg=f"Unexpected error: {str(e)}", args=(), exc_info=None))

    return config_dict, log_records

