def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import json
    import os
    import sys

    def resolve_environment_variables(config):
        if isinstance(config, dict):
            return {k: resolve_environment_variables(v) for k, v in config.items()}
        elif isinstance(config, list):
            return [resolve_environment_variables(i) for i in config]
        elif isinstance(config, str) and config.startswith('$'):
            return os.getenv(config[1:])
        else:
            return config

    def load_config(filename):
        try:
            with open(filename, 'r') as f:
                config = json.load(f)
            if resolve_env:
                config = resolve_environment_variables(config)
            return config
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {filename}")
            return None
        except json.JSONDecodeError:
            logging.error(f"Invalid JSON in configuration file: {filename}")
            return None

    def apply_overrides(config, overrides):
        if overrides:
            config.update(overrides)
        return config

    configs = {}
    errors = []

    for filename in config_filenames:
        config = load_config(filename)
        if config is None:
            continue

        config = apply_overrides(config, overrides)
        configs[filename] = config

    return configs, errors

