def from_ticks(ticks, tz=None):
    if not (0 <= ticks < 86400000000000):
        raise ValueError('ticks out of bounds (0 <= ticks < 86400000000000)')
    seconds, nanoseconds = divmod(ticks, 10**9)
    hours, remainder = divmod(seconds, 3600)
    minutes, seconds = divmod(remainder, 60)
    return cls(hours, minutes, seconds, nanoseconds, tz)

@classmethod
    def from_ticks(cls, ticks, tz=None):
        """Create a time from ticks (nanoseconds since midnight).

        :param ticks: nanoseconds since midnight
        :type ticks: int
        :param tz: optional timezone
        :type tz: datetime.tzinfo

        :rtype: Time

        :raises ValueError: if ticks is out of bounds
            (0 <= ticks < 86400000000000)
        """
        if not (0 <= ticks < 86400000000000):
            raise ValueError("ticks is out of bounds (0 <= ticks < 86400000000000)")

        seconds = ticks // 10**9
        nanoseconds = ticks % 10**9

        dt = datetime.datetime(1970, 1, 1) + datetime.timedelta(seconds=seconds, microseconds=nanoseconds // 1000)
        dt = dt.replace(tzinfo=cls._make_timezone(tz))

        return cls(dt)

    @staticmethod
    def _make_timezone(tzinfo):
        if tzinfo is None:
            return datetime.timezone.utc
        return tzinfo

