    from zope.interface import implements, provider, Invalid

    if not tentative:
        if not iface.providedBy(candidate):
            raise Invalid(f"Candidate does not claim to provide the interface {iface}")

    candidate_methods = set(candidate.__dict__.keys())
    required_methods = {method for method in iface.names() if callable(iface[method])}
    if not required_methods.issubset(candidate_methods):
        missing_methods = required_methods - candidate_methods
        if vtype and vtype == 'method':
            raise Invalid(f"Candidate is missing the following methods: {missing_methods}")
        else:
            raise Invalid(f"Candidate is missing the following methods: {missing_methods}")

    for method in required_methods:
        method_obj = getattr(candidate, method)
        if not callable(method_obj) or not ismethod(method_obj):
            raise Invalid(f"Method {method} in candidate is not a callable method")

    required_attributes = set(iface.names()) - required_methods
    candidate_attributes = set(candidate.__dict__.keys())
    if not required_attributes.issubset(candidate_attributes):
        missing_attributes = required_attributes - candidate_attributes
        if vtype and vtype == 'attribute':
            raise Invalid(f"Candidate is missing the following attributes: {missing_attributes}")
        else:
            raise Invalid(f"Candidate is missing the following attributes: {missing_attributes}")

    return True

