class CustomDateTimeParser:
    @_takes_ascii
    def isoparse(self, dt_str):
        pattern_common_date = re.compile(r'(\d{4})(-(\d{2})(-(\d{2}))?)?')
        pattern_uncommon_date = re.compile(r'(\d{4})-(W(\d{2})(-(\d{1})))?')
        pattern_time = re.compile(r'(\d{2}):?(\d{2})?:(\d{2})?(\.\d{1,6})?')
        pattern_timezone = re.compile(r'([Zz]|([-+])(\d{2}):?(\d{2})?([\.,]\d+)?)')

        def parse_date(date_match):
            year = int(date_match.group(1))
            month = int(date_match.group(3)) if date_match.group(3) else 1
            day = int(date_match.group(5)) if date_match.group(5) else 1
            return year, month, day

        def parse_time(time_match):
            hour = int(time_match.group(1))
            minute = int(time_match.group(2)) if time_match.group(2) else 0
            second = int(time_match.group(3)) if time_match.group(3) else 0
            microsecond = int((time_match.group(4) or '.0').lstrip('.').rstrip(',')) * 1000 if time_match.group(4) else 0
            return hour, minute, second, microsecond

        def parse_timezone(tz_match):
            if tz_match.group(1) in ('Z', 'z'):
                return tzutc
            sign = 1 if tz_match.group(2) == '+' else -1
            hours = int(tz_match.group(3))
            minutes = int(tz_match.group(4)) if tz_match.group(4) else 0
            return tzoffset(None, sign * (hours * 3600 + minutes * 60))

        date_parts = None
        time_parts = None
        tz_parts = None

        if date_str:
            date_match = pattern_common_date.search(dt_str) or pattern_uncommon_date.search(dt_str)
            if date_match:
                date_parts = parse_date(date_match)

        if date_parts:
            time_match = pattern_time.search(dt_str.removeprefix(dt_str.split(date_parts[0]).pop(0)))
            if time_match:
                time_parts = parse_time(time_match)

        if time_parts:
            tz_match = pattern_timezone.search(dt_str.removeprefix(dt_str.split(time_parts[0].lstrip(',').lstrip('.')).pop(0)))
            if tz_match:
                tz_parts = parse_timezone(tz_match)

        year, month, day = date_parts if date_parts else (1970, 1, 1)
        hour, minute, second, microsecond = time_parts if time_parts else (0, 0, 0, 0)
        tzinfo_obj = tz_parts if tz_parts else timezone.utc

        return datetime(year, month, day, hour, minute, second, microsecond, tzinfo=tzinfo_obj)

