def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    spec_file_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.exists(spec_file_path):
        raise FileNotFoundError(f"Plugin spec file not found at {spec_file_path}")

    with open(spec_file_path, 'r') as file:
        spec_dict = json.load(file)

    def flatten(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten(spec_dict)

